<script setup>
import { computed, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { jointStore as store, clone } from '../../data/equipmentInspectionMock.js'
import { ROOT_TYPES, INPUT_TYPES, DEMO_BASIS } from '../../data/equipmentInspectionSeed.js'
import RulePreview from './RulePreview.vue'
import GroupMatchingEditor from './GroupMatchingEditor.vue'
const filters=ref({text:'',status:'',type:''}), applied=ref(clone(filters.value)), page=ref(1)
const rows=computed(()=>store.state.rules.filter(row=>(!applied.value.text || `${row.code}${row.name}`.includes(applied.value.text)) && (!applied.value.status || row.status===applied.value.status) && (!applied.value.type || row.rootType===applied.value.type)))
function query(){applied.value=clone(filters.value);applied.value.text=applied.value.text.trim();page.value=1}
function reset(){filters.value={text:'',status:'',type:''};query()}
const show=ref(false), draft=ref({}), error=ref(''), copying=ref(false), previewId=ref(''), sections=ref([0])
const previewRule=computed(()=>store.byId(store.state.rules,previewId.value))
function newItem(){return{id:'',name:'',type:'数值',unit:'',options:[],normalOptions:[],required:true,lower:'',upper:'',basis:'',demoReference:true,method:'',models:[],states:[],exceptionNote:true,exceptionPhoto:false,guidance:'异常时请报告并按院方已批准预案处置（演示提示）。'}}
function addGroup(){draft.value.groups.push({id:'',name:'',role:'self',categoryId:'',targetType:'',models:[],states:[],extraRoles:[],required:true,items:[newItem()]});sections.value.push(draft.value.groups.length-1)}
function open(row,copy=false){copying.value=copy;draft.value=row?clone(row):{id:'',code:'',name:'',version:1,status:'草稿',rootType:'设备',categoryId:'',roomUsage:'',models:[],states:[],scene:'运行抄表',basis:DEMO_BASIS,notes:'',groups:[]};draft.value.groups.forEach(group=>{group.role=store.normalizedRole(group.role,draft.value.rootType);group.models ||= [];group.states ||= [];group.extraRoles ||= []});if(copy){draft.value.code='';draft.value.name+='（副本）'}if(!row)addGroup();error.value='';sections.value=[0];show.value=true}
function changeRoot(){draft.value.categoryId='';draft.value.roomUsage='';draft.value.models=[];draft.value.states=[]}
function changeItemType(item){item.unit='';item.lower='';item.upper='';item.options=item.type==='状态'?['正常','异常']:[];item.normalOptions=item.type==='状态'?['正常']:[];item.basis=''}
function move(list,index,offset){const target=index+offset;if(target>=0 && target<list.length){const [row]=list.splice(index,1);list.splice(target,0,row)}}
function copyGroup(group){const copied=clone(group);copied.id='';copied.name+='（复用）';copied.items.forEach(item=>item.id='');draft.value.groups.push(copied);sections.value.push(draft.value.groups.length-1)}
function save(publish){try{const saved=store.saveRule(draft.value,publish,copying.value);show.value=false;ElMessage.success(`已保存 ${saved.name} V${saved.version}（${saved.status}），旧任务与记录保持原快照`)}catch(e){error.value=e.message}}
function toggle(row){try{store.toggleRule(row.id);ElMessage.success(row.status==='已停用'?'规则已停用；已有任务保留，后续生成需有效规则':'规则已启用')}catch(e){ElMessage.error(e.message)}}
</script>
<template>
  <main class="inspection-page"><header class="heading"><div><div class="eyebrow">巡检管理 / 检查要求</div><h1>巡检规则</h1><p class="subtitle">检查项唯一编制入口。先定义检查表，再由计划一次应用到实际对象。</p></div><el-button type="primary" @click="open()">新增规则</el-button></header><p class="demo-note">本地 Mock 演示 · 数值参考条件均为明显标识的模拟值。已启用规则编辑时形成新版，不覆盖原版本或已生成任务。</p><el-alert v-if="store.notice.catalog" :title="store.notice.catalog" type="warning" :closable="false" /><el-alert v-if="store.notice.persistence" :title="store.notice.persistence" type="warning" :closable="false" />
    <section class="panel"><el-form class="filters" @submit.prevent="query"><el-input v-model="filters.text" aria-label="规则查询" placeholder="规则名称 / 编号" clearable /><el-select v-model="filters.type" aria-label="规则适用类型" placeholder="全部适用类型" clearable><el-option v-for="type in ROOT_TYPES" :key="type" :value="type" /></el-select><el-select v-model="filters.status" aria-label="规则状态" placeholder="全部规则状态" clearable><el-option v-for="status in ['草稿','已启用','已停用']" :key="status" :value="status" /></el-select><el-button native-type="submit" type="primary">查询</el-button><el-button @click="reset">重置</el-button></el-form><p class="caption">共 {{ rows.length }} 个规则版本 · 每个版本独立保留；定义项目数不等于实际巡检项数，数量以计划展开为准</p>
      <el-table :data="rows.slice((page-1)*10,page*10)" stripe empty-text="暂无符合条件的规则"><el-table-column label="规则 / 版本" min-width="230"><template #default="{row}"><el-button link type="primary" class="title-button" @click="previewId=row.id">{{ row.name }}</el-button><div class="muted">{{ row.code }} · V{{ row.version }}</div></template></el-table-column><el-table-column prop="scene" label="场景" min-width="110" /><el-table-column label="适用对象" min-width="170"><template #default="{row}">{{ row.rootType }} · {{ row.roomUsage || store.byId(store.state.categories,row.categoryId)?.name || '按分组条件' }}</template></el-table-column><el-table-column label="检查表定义" width="110"><template #default="{row}">{{ row.groups.length }} 组 / {{ row.groups.reduce((sum,g)=>sum+g.items.length,0) }} 项</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='已启用'?'success':'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="245" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{ row.status==='草稿'?'编辑':'编辑新版' }}</el-button><el-button link @click="open(row,true)">复制</el-button><el-button link @click="previewId=row.id">预览</el-button><el-button link @click="toggle(row)">{{ row.status==='已启用'?'停用':'启用' }}</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="rows.length" :page-size="10" layout="total, prev, pager, next" class="pagination" /></section>
    <el-dialog v-model="show" :title="copying?'复制为新规则':draft.id && draft.status!=='草稿'?'编辑规则 · 保存为新版本':'编制巡检规则'" width="min(1100px,94vw)" class="ez-dialog inspection-editor" align-center append-to-body destroy-on-close>
      <p class="demo-note">不选择实际锅炉 / 机房。参考值只用于演示；无有效依据只采集、不判正常。</p><el-form class="form-grid" label-position="top" @submit.prevent="save(false)"><el-form-item label="规则编号" required><el-input v-model="draft.code" :disabled="Boolean(draft.id && !copying)" maxlength="40" /></el-form-item><el-form-item label="规则名称" required><el-input v-model="draft.name" maxlength="80" /></el-form-item><el-form-item label="场景 / 专业" required><el-select v-model="draft.scene"><el-option v-for="scene in ['运行抄表','机房综合检查','设施检查','系统检查']" :key="scene" :value="scene" /></el-select></el-form-item><el-form-item label="适用对象类型" required><el-select v-model="draft.rootType" @change="changeRoot"><el-option v-for="type in ROOT_TYPES" :key="type" :value="type" /></el-select></el-form-item><el-form-item v-if="draft.rootType!=='空间'" label="适用分类 / 条件"><el-select v-model="draft.categoryId" filterable clearable placeholder="通用分类，不是实际设备"><el-option v-for="row in store.state.categories.filter(cat=>cat.enabled)" :key="row.id" :value="row.id" :label="store.categoryPath(row.id)" /></el-select></el-form-item><el-form-item v-else label="适用机房用途"><el-select v-model="draft.roomUsage" allow-create filterable clearable><el-option v-for="usage in ['锅炉房','压缩空气机房','配电房']" :key="usage" :value="usage" /></el-select></el-form-item><el-form-item label="适用型号（留空表示不限定）"><el-select v-model="draft.models" multiple filterable allow-create default-first-option><el-option v-for="model in [...new Set(store.state.assets.map(row=>row.model).filter(Boolean))]" :key="model" :value="model" /></el-select></el-form-item><el-form-item label="适用工况"><el-select v-model="draft.states" multiple clearable><el-option v-for="status in ['运行','备用','停用']" :key="status" :value="status" /></el-select></el-form-item><el-form-item label="依据 / 标准来源"><el-input v-model="draft.basis" maxlength="300" /></el-form-item><el-form-item label="适用说明" class="wide"><el-input v-model="draft.notes" type="textarea" :rows="2" maxlength="500" /></el-form-item></el-form>
      <p v-if="draft.rootType==='设施'" class="demo-note">设施范围包括一般设施和建筑构件；请在检查分组中分别指定实际作用对象类型，并按分类筛选，二者不会互相代替。</p>
      <div class="between section"><h2>检查分组与检查项</h2><el-button type="primary" plain @click="addGroup">新增分组</el-button></div>
      <el-collapse v-model="sections"><el-collapse-item v-for="(group,gi) in draft.groups" :key="gi" :name="gi" :title="`${gi+1}. ${group.name || '未命名分组'} · ${group.items.length}项`"><div class="group-card"><div class="actions"><el-button size="small" :disabled="gi===0" @click="move(draft.groups,gi,-1)">上移组</el-button><el-button size="small" :disabled="gi===draft.groups.length-1" @click="move(draft.groups,gi,1)">下移组</el-button><el-button size="small" @click="copyGroup(group)">复用此组</el-button><el-button size="small" type="danger" plain @click="draft.groups.splice(gi,1)">移除分组</el-button></div><GroupMatchingEditor :group="group" :root-type="draft.rootType" />
        <article v-for="(item,ii) in group.items" :key="ii" class="item-editor"><div class="between"><h3>检查项 {{ ii+1 }} · {{ item.name || '待编制' }}</h3><div class="actions"><el-button link :disabled="ii===0" @click="move(group.items,ii,-1)">上移</el-button><el-button link :disabled="ii===group.items.length-1" @click="move(group.items,ii,1)">下移</el-button><el-button link type="danger" @click="group.items.splice(ii,1)">移除项</el-button></div></div><el-form class="form-grid" label-position="top"><el-form-item label="检查项名称" required><el-input v-model="item.name" maxlength="100" /></el-form-item><el-form-item label="输入类型" required><el-select v-model="item.type" @change="changeItemType(item)"><el-option v-for="type in INPUT_TYPES" :key="type" :value="type" /></el-select></el-form-item><el-form-item label="检查方法 / 读取位置" class="wide"><el-input v-model="item.method" maxlength="300" /></el-form-item>
          <template v-if="item.type==='数值'"><el-form-item label="计量单位" required><el-input v-model="item.unit" maxlength="20" /></el-form-item><el-form-item label="数值参考下限（可留空）"><el-input v-model="item.lower" inputmode="decimal" /></el-form-item><el-form-item label="数值参考上限（可留空）"><el-input v-model="item.upper" inputmode="decimal" /></el-form-item></template><template v-if="item.type==='状态'"><el-form-item label="可选状态（输入后回车添加）" required><el-select v-model="item.options" multiple filterable allow-create default-first-option @change="item.normalOptions=item.normalOptions.filter(option=>item.options.includes(option))"><el-option v-for="option in item.options" :key="option" :value="option" /></el-select></el-form-item><el-form-item label="正常选项"><el-select v-model="item.normalOptions" multiple><el-option v-for="option in item.options" :key="option" :value="option" /></el-select></el-form-item></template>
          <el-form-item label="判断依据"><el-input v-model="item.basis" maxlength="300" placeholder="无依据时仅采集、未自动判定" /></el-form-item><el-form-item label="参考值标识"><el-checkbox v-model="item.demoReference" disabled>模拟演示值，不是现场标准</el-checkbox></el-form-item><el-form-item label="本项额外型号条件（可选）"><el-select v-model="item.models" multiple filterable allow-create default-first-option><el-option v-for="model in [...new Set(store.state.assets.map(row=>row.model).filter(Boolean))]" :key="model" :value="model" /></el-select></el-form-item><el-form-item label="本项额外工况条件（可选）"><el-select v-model="item.states" multiple clearable><el-option v-for="status in ['运行','备用','停用']" :key="status" :value="status" /></el-select></el-form-item><el-form-item label="填写要求"><el-checkbox v-model="item.required">必检，不填不能提交</el-checkbox></el-form-item><el-form-item label="异常补充要求"><el-checkbox v-model="item.exceptionNote">必填异常说明</el-checkbox><el-checkbox v-model="item.exceptionPhoto" @change="value=>{if(value)item.exceptionNote=true}">必附照片</el-checkbox></el-form-item><el-form-item label="处置提示 / 已批准SOP引用说明" class="wide"><el-input v-model="item.guidance" type="textarea" :rows="2" maxlength="500" /></el-form-item></el-form></article><el-button @click="group.items.push(newItem())">添加检查项</el-button></div></el-collapse-item></el-collapse>
      <p v-if="error" class="error-box" role="alert">{{ error }}</p><template #footer><p class="footer-note">保存后可预览；启用前核对检查内容和模拟参考条件。执行时不预选正常。</p><div class="actions"><el-button @click="show=false">取消</el-button><el-button @click="save(false)">保存草稿</el-button><el-button type="primary" @click="save(true)">核对并启用规则</el-button></div></template>
    </el-dialog>
    <el-drawer :model-value="Boolean(previewRule)" title="规则检查表预览" size="min(800px,94vw)" append-to-body @close="previewId=''"><RulePreview v-if="previewRule" :rule="previewRule" /></el-drawer>
  </main>
</template>
<style scoped src="./inspection.css"></style>
